style.css:
@-moz-document domain("youtube.com") {
:root {
  --my-bg: #071329;
  --my-panel: #0b1b38;
  --my-blue: #315b91;
  --my-glow: #8bbcff;
}

/* Main background */
ytd-app,
ytd-page-manager,
#contentContainer {
  background: var(--my-bg) !important;
}

/* Header */
#masthead-container {
  background: rgba(5, 15, 35, 0.96) !important;
  backdrop-filter: blur(12px) !important;
}

/* Sidebar */
#guide,
ytd-mini-guide-renderer {
  background: var(--my-panel) !important;
}

/* Video panels */
ytd-browse,
ytd-watch-flexy,
#primary,
#secondary {
  background: transparent !important;
}

/* Search bar */
#container.ytd-searchbox {
  background: #102342 !important;
  border: 1px solid #294b78 !important;
  border-radius: 20px !important;
}

/* Thumbnails */
ytd-thumbnail {
  border-radius: 14px !important;
  overflow: hidden !important;
}

/* Blue hover effects */
ytd-guide-entry-renderer:hover {
  background: rgba(100, 160, 255, 0.15) !important;
}

/* Scrollbar */
::-webkit-scrollbar-thumb {
  background: var(--my-blue) !important;
  border-radius: 10px !important;
}
}
